import jsonimport pandas as pdfrom collections import defaultdictimport os# --- Configuration ---INPUT_FILE = "aj.json"OUTPUT_MAPPING_FILE = "mapped_attack_data.csv"OUTPUT_SUMMARY_FILE = "behavior_summary.csv"# --- Main Extraction and Mapping Function ---def extract_malware_data(input_file):    """    Loads the consolidated JSON reports and extracts key behavioral and ATT&CK data.    """    if not os.path.exists(input_file):        print(f"Error: Input file '{input_file}' not found. Please ensure it is in the same directory.")        return []    with open(input_file, 'r') as f:        try:            reports = json.load(f)        except json.JSONDecodeError:            print("Error: Could not decode JSON. Check file integrity.")            return []    mapped_data = []    # We will assume a static list of hashes or generate a unique ID for each report    report_id_counter = 1    for report_entry in reports:        # Skip null reports        if not report_entry or not report_entry.get('data'):            continue        data = report_entry['data']        # 1. Identify the Malware Family (use first verdict or placeholder)        family = data.get('verdict_labels', ["Unknown"])[0]        # 2. Extract Pre-mapped ATT&CK Techniques        # This is the most reliable source, as the sandbox already did the heavy lifting.        techniques = set()        if 'mitre_attack_techniques' in data:            for tech_entry in data['mitre_attack_techniques']:                # Extract the base ID (e.g., T1059 or T1059.001)                techniques.add(tech_entry.get('id', 'T_Unknown'))        # 3. Extract Raw Behaviors (for validation and deeper understanding)        # We assume a fixed hash/ID for the sample since the report doesn't explicitly link.        sample_id = f"Sample_{report_id_counter}"        # Extract C2 and suspicious network traffic        c2_domains = [d.get('hostname') for d in data.get('dns_lookups', []) if d.get('hostname') not in ['time.windows.com', 'ln-0007.ln-msedge.net']]        c2_ips = [t.get('destination_ip') for t in data.get('ip_traffic', []) if t.get('destination_port') in [80, 443, 587]]        # Extract suspicious commands        suspicious_commands = []        for cmd in data.get('command_executions', []):            # Capture PowerShell execution (T1059.001) and mshta (T1218.005) for manual review            if 'powershell' in cmd.lower() or 'mshta' in cmd.lower() or 'schtasks' in cmd.lower() or 'ping' in cmd.lower():                suspicious_commands.append(cmd)        # Store results for final CSV        for tech_id in sorted(list(techniques)):            mapped_data.append({                'Sample_ID': sample_id,                'Malware_Family': family,                'ATTACK_ID': tech_id,                'Observed_Technique': next((t['signature_description'] for t in data.get('mitre_attack_techniques', []) if t.get('id') == tech_id), 'N/A'),                'C2_Domains': '|'.join(set(c2_domains)),                'C2_IPs': '|'.join(set(c2_ips)),                'Evidence_Count': len(techniques),                'Has_Injection_Evidence': 'processes_injected' in data and len(data['processes_injected']) > 0            })        report_id_counter += 1    return mapped_data# --- Execution Block ---def main():    print(f"--- Starting Data Extraction from {INPUT_FILE} ---")    extracted_data = extract_malware_data(INPUT_FILE)    if not extracted_data:        print("No valid data extracted. Exiting.")        return    # Convert to DataFrame    df = pd.DataFrame(extracted_data)    # Clean up the output by dropping duplicate mappings for the same technique/sample    df_clean = df.drop_duplicates(subset=['Sample_ID', 'ATTACK_ID'])    # 1. Save the primary mapped data (fulfills mapping objective)    df_clean.to_csv(OUTPUT_MAPPING_FILE, index=False)    print(f"\n✅ Successfully extracted and mapped data. Saved to: {OUTPUT_MAPPING_FILE}")    # 2. Generate a frequency summary (helps fulfill pattern/trend objective)    tech_counts = df_clean.groupby('ATTACK_ID').agg(        Total_Count=('Sample_ID', 'count'),        Unique_Families=('Malware_Family', pd.Series.nunique),        Families=('Malware_Family', lambda x: '|'.join(sorted(x.unique())))    ).sort_values(by='Total_Count', ascending=False).reset_index()    tech_counts.to_csv(OUTPUT_SUMMARY_FILE, index=False)    print(f"📈 Technique Frequency Summary saved to: {OUTPUT_SUMMARY_FILE}")    # Provide key instructions    print("\n--- Next Steps for Your Project ---")    print(        f"1. **Analysis & Mapping (Completed by script):** The file '{OUTPUT_MAPPING_FILE}' contains the mapped ATT&CK IDs (e.g., T1055, T1059.001) for the samples identified.")    print(        "2. **Identify Trends:** Review the file '{OUTPUT_SUMMARY_FILE}' to easily find the Top N most frequent techniques and which malware families use them. This fulfills the 'Identify trends and patterns' objective.")    print(        "3. **Visualization:** Upload the data in '{OUTPUT_MAPPING_FILE}' or '{OUTPUT_SUMMARY_FILE}' to the ATT&CK Navigator tool (https://mitre-attack.github.io/attack-navigator/) to create a colored heat map.")# --- Run the script ---if __name__ == "__main__":    main()